import{f as a,ag as n,o as e,s as l}from"./chunks/framework.D85dHE_g.js";const m=JSON.parse('{"title":"chrome-plugin API","description":"","frontmatter":{},"headers":[],"relativePath":"大前端/前端工具/chrome-plugin.md","filePath":"大前端/前端工具/chrome-plugin.md","lastUpdated":1731317022000}'),p={name:"大前端/前端工具/chrome-plugin.md"};function i(r,s,c,o,t,b){return n(),e("div",null,s[0]||(s[0]=[l(`<h1 id="chrome-plugin-api" tabindex="-1">chrome-plugin API <a class="header-anchor" href="#chrome-plugin-api" aria-label="Permalink to &quot;chrome-plugin API&quot;">​</a></h1><p>记录chrome插件相关的一些API</p><h2 id="_1-chrome-storage-local" tabindex="-1">1. chrome.storage.local <a class="header-anchor" href="#_1-chrome-storage-local" aria-label="Permalink to &quot;1. chrome.storage.local&quot;">​</a></h2><p>chrome.storage.local 是 Chrome 插件 API 中的一个存储接口，用于本地存储数据。与浏览器的 localStorage 类似，但更强大且容量更大（一般为 5MB），在 Chrome 扩展的各个组件（如 Background Script、Content Script、Popup、Options 页面等）之间都可以共享数据。</p><h3 id="_1-1-设置数据-chrome-storage-local-set" tabindex="-1">1.1 设置数据：chrome.storage.local.set() <a class="header-anchor" href="#_1-1-设置数据-chrome-storage-local-set" aria-label="Permalink to &quot;1.1 设置数据：chrome.storage.local.set()&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 在插件的某处保存数据</span></span>
<span class="line"><span>chrome.storage.local.set({ key: &#39;value&#39; }, function() {</span></span>
<span class="line"><span>  console.log(&#39;Data is saved.&#39;);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 保存多个键值对</span></span>
<span class="line"><span>chrome.storage.local.set({ key1: &#39;value1&#39;, key2: &#39;value2&#39; });</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_1-2-获取数据-chrome-storage-local-get" tabindex="-1">1.2 获取数据：chrome.storage.local.get() <a class="header-anchor" href="#_1-2-获取数据-chrome-storage-local-get" aria-label="Permalink to &quot;1.2 获取数据：chrome.storage.local.get()&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 获取指定的键</span></span>
<span class="line"><span>chrome.storage.local.get([&#39;key&#39;], function(result) {</span></span>
<span class="line"><span>  console.log(&#39;Value currently is &#39; + result.key);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 获取多个键的数据</span></span>
<span class="line"><span>chrome.storage.local.get([&#39;key1&#39;, &#39;key2&#39;], function(result) {</span></span>
<span class="line"><span>  console.log(&#39;Key1:&#39;, result.key1);</span></span>
<span class="line"><span>  console.log(&#39;Key2:&#39;, result.key2);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 获取所有数据</span></span>
<span class="line"><span>chrome.storage.local.get(null, function(result) {</span></span>
<span class="line"><span>  console.log(&#39;All data:&#39;, result);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h3 id="_1-3-删除数据-chrome-storage-local-remove" tabindex="-1">1.3 删除数据：chrome.storage.local.remove() <a class="header-anchor" href="#_1-3-删除数据-chrome-storage-local-remove" aria-label="Permalink to &quot;1.3 删除数据：chrome.storage.local.remove()&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 删除指定的键</span></span>
<span class="line"><span>chrome.storage.local.remove([&#39;key&#39;], function() {</span></span>
<span class="line"><span>  console.log(&#39;Key is removed&#39;);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_1-4-清空数据-chrome-storage-local-clear" tabindex="-1">1.4 清空数据：chrome.storage.local.clear() <a class="header-anchor" href="#_1-4-清空数据-chrome-storage-local-clear" aria-label="Permalink to &quot;1.4 清空数据：chrome.storage.local.clear()&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chrome.storage.local.clear(function() {</span></span>
<span class="line"><span>  console.log(&#39;All data is cleared&#39;);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_1-5-监听存储变化-chrome-storage-onchanged" tabindex="-1">1.5 监听存储变化：chrome.storage.onChanged <a class="header-anchor" href="#_1-5-监听存储变化-chrome-storage-onchanged" aria-label="Permalink to &quot;1.5 监听存储变化：chrome.storage.onChanged&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chrome.storage.onChanged.addListener(function(changes, areaName) {</span></span>
<span class="line"><span>  if (areaName === &#39;local&#39;) {</span></span>
<span class="line"><span>    console.log(&#39;Changes in local storage:&#39;, changes);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="_2-chrome-storage-sync" tabindex="-1">2. chrome.storage.sync <a class="header-anchor" href="#_2-chrome-storage-sync" aria-label="Permalink to &quot;2. chrome.storage.sync&quot;">​</a></h2><p>chrome.storage.sync 是 Chrome 扩展提供的一个同步存储接口，它允许将数据与用户的 Google 帐户同步，从而在用户的多个设备上共享数据。相比 chrome.storage.local 的本地存储，chrome.storage.sync 的数据会在用户的所有 Chrome 浏览器中同步，只要用户使用同一帐户登录。</p><h3 id="_2-1-设置数据-chrome-storage-sync-set" tabindex="-1">2.1 设置数据：chrome.storage.sync.set() <a class="header-anchor" href="#_2-1-设置数据-chrome-storage-sync-set" aria-label="Permalink to &quot;2.1 设置数据：chrome.storage.sync.set()&quot;">​</a></h3><h3 id="_2-2-获取数据-chrome-storage-sync-get" tabindex="-1">2.2 获取数据：chrome.storage.sync.get() <a class="header-anchor" href="#_2-2-获取数据-chrome-storage-sync-get" aria-label="Permalink to &quot;2.2 获取数据：chrome.storage.sync.get()&quot;">​</a></h3><h3 id="_2-3-删除数据-chrome-storage-sync-remove" tabindex="-1">2.3 删除数据：chrome.storage.sync.remove() <a class="header-anchor" href="#_2-3-删除数据-chrome-storage-sync-remove" aria-label="Permalink to &quot;2.3 删除数据：chrome.storage.sync.remove()&quot;">​</a></h3><h3 id="_2-4-清空数据-chrome-storage-sync-clear" tabindex="-1">2.4 清空数据：chrome.storage.sync.clear() <a class="header-anchor" href="#_2-4-清空数据-chrome-storage-sync-clear" aria-label="Permalink to &quot;2.4 清空数据：chrome.storage.sync.clear()&quot;">​</a></h3><h3 id="_2-5-监听存储变化-chrome-storage-onchanged" tabindex="-1">2.5 监听存储变化：chrome.storage.onChanged <a class="header-anchor" href="#_2-5-监听存储变化-chrome-storage-onchanged" aria-label="Permalink to &quot;2.5 监听存储变化：chrome.storage.onChanged&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chrome.storage.onChanged.addListener(function(changes, areaName) {</span></span>
<span class="line"><span>  if (areaName === &#39;sync&#39;) {</span></span>
<span class="line"><span>    console.log(&#39;Changes in local storage:&#39;, changes);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="_3-chrome-tabs" tabindex="-1">3. chrome.tabs <a class="header-anchor" href="#_3-chrome-tabs" aria-label="Permalink to &quot;3. chrome.tabs&quot;">​</a></h2><p>chrome.tabs 是 Chrome 扩展 API 中用于操作浏览器标签页的模块，提供了丰富的功能，可以帮助开发者在插件中创建、查询、更新和管理标签页。</p><h3 id="_3-1-创建新标签页-chrome-tabs-create" tabindex="-1">3.1 创建新标签页：chrome.tabs.create() <a class="header-anchor" href="#_3-1-创建新标签页-chrome-tabs-create" aria-label="Permalink to &quot;3.1 创建新标签页：chrome.tabs.create()&quot;">​</a></h3><p>chrome.tabs.create(options, callback) 方法用于创建新的标签页。</p><p>参数：</p><ul><li>options：一个对象，包含创建标签页的选项。 <ul><li>url：要打开的 URL。</li><li>active：是否将新标签页设置为活动标签页。</li></ul></li><li>callback(tab)：一个回调函数，在标签页创建完成后执行。 <ul><li>一个对象，包含新标签页的信息。信息包括标签页的 ID、URL 等。</li><li>如果创建失败，返回错误信息。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chrome.tabs.create({ url: &#39;https://example.com&#39;, active: true }, function(tab) {</span></span>
<span class="line"><span>  console.log(&#39;New tab created:&#39;, tab);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_3-2-查询当前标签页-chrome-tabs-query" tabindex="-1">3.2 查询当前标签页：chrome.tabs.query() <a class="header-anchor" href="#_3-2-查询当前标签页-chrome-tabs-query" aria-label="Permalink to &quot;3.2 查询当前标签页：chrome.tabs.query()&quot;">​</a></h3><p>chrome.tabs.query(queryInfo, callback) 方法用于查询当前标签页。</p><p>参数：</p><ul><li>queryInfo：一个对象，包含查询条件。 <ul><li>active：是否查询活动标签页。</li><li>currentWindow：是否查询当前窗口的标签页。</li><li>其他属性：根据标签页的属性进行查询，如 url、title 等。</li><li>可以使用多个属性进行组合查询。</li><li>可以使用通配符 * 进行模糊匹配。</li></ul></li><li>callback(tabs)：一个回调函数，在查询完成后执行。 <ul><li>一个数组，包含符合条件的标签页信息。</li><li>如果查询失败，返回错误信息。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 查询所有活动标签页</span></span>
<span class="line"><span>chrome.tabs.query({ active: true, currentWindow: true }, function(tabs) {</span></span>
<span class="line"><span>  console.log(&#39;Active tab:&#39;, tabs[0]);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 查询所有标签页</span></span>
<span class="line"><span>chrome.tabs.query({}, function(tabs) {</span></span>
<span class="line"><span>  console.log(&#39;All tabs:&#39;, tabs);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_3-3-更新标签页-chrome-tabs-update" tabindex="-1">3.3 更新标签页：chrome.tabs.update() <a class="header-anchor" href="#_3-3-更新标签页-chrome-tabs-update" aria-label="Permalink to &quot;3.3 更新标签页：chrome.tabs.update()&quot;">​</a></h3><p>chrome.tabs.update(tabId, updateProperties, callback) 方法用于更新指定标签页的属性。</p><p>参数：</p><ul><li>tabId(Number)：要更新的标签页的 ID。</li><li>updateProperties(Options)：一个对象，包含要更新的属性。</li><li>callback(Options)：一个回调函数，在更新完成后执行。 <ul><li>一个对象，包含更新后的标签页信息。</li><li>如果更新失败，返回错误信息。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 更新标签页的 URL</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.tabs.update(tabId, { url: &#39;URL_ADDRESS&#39; }, function(tab) {</span></span>
<span class="line"><span>  console.log(&#39;Tab updated:&#39;, tab);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_3-4-关闭标签页-chrome-tabs-remove" tabindex="-1">3.4 关闭标签页：chrome.tabs.remove() <a class="header-anchor" href="#_3-4-关闭标签页-chrome-tabs-remove" aria-label="Permalink to &quot;3.4 关闭标签页：chrome.tabs.remove()&quot;">​</a></h3><p>chrome.tabs.remove(tabId, callback) 方法用于关闭指定标签页。</p><p>参数：</p><ul><li>tabId(Number)：要关闭的标签页的 ID。</li><li>callback()：一个回调函数，在关闭完成后执行。 <ul><li>如果关闭失败，返回错误信息。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 关闭标签页</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.tabs.remove(tabId, function() {</span></span>
<span class="line"><span>  console.log(&#39;Tab closed&#39;);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_3-5-监听标签页变化-chrome-tabs-onupdated" tabindex="-1">3.5 监听标签页变化：chrome.tabs.onUpdated <a class="header-anchor" href="#_3-5-监听标签页变化-chrome-tabs-onupdated" aria-label="Permalink to &quot;3.5 监听标签页变化：chrome.tabs.onUpdated&quot;">​</a></h3><p>chrome.tabs.onUpdated.addListener(callback) 方法用于监听标签页的变化。</p><p>参数：</p><ul><li>callback(tabId, changeInfo, tab)：一个回调函数，在标签页变化时执行。 <ul><li>tabId(Number)：发生变化的标签页的 ID。</li><li>changeInfo(Options)：一个对象，包含标签页变化的信息。</li><li>tab(Options)：一个对象，包含发生变化的标签页的信息。</li><li>如果监听失败，返回错误信息。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 监听标签页变化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.tabs.onUpdated.addListener(function(tabId, changeInfo, tab) {</span></span>
<span class="line"><span>  console.log(&#39;Tab updated:&#39;, tabId, changeInfo, tab);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_3-6-监听标签页激活-chrome-tabs-onactivated" tabindex="-1">3.6 监听标签页激活：chrome.tabs.onActivated <a class="header-anchor" href="#_3-6-监听标签页激活-chrome-tabs-onactivated" aria-label="Permalink to &quot;3.6 监听标签页激活：chrome.tabs.onActivated&quot;">​</a></h3><p>chrome.tabs.onActivated.addListener(callback) 方法用于监听标签页的激活。</p><p>参数：</p><ul><li>callback(activeInfo)：一个回调函数，在标签页激活时执行。 <ul><li>activeInfo(Options)：一个对象，包含激活的标签页的信息。</li><li>如果监听失败，返回错误信息。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 监听标签页激活</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.tabs.onActivated.addListener(function(activeInfo) {</span></span>
<span class="line"><span>  console.log(&#39;Tab activated:&#39;, activeInfo);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_3-7-监听标签页关闭-chrome-tabs-onremoved" tabindex="-1">3.7 监听标签页关闭：chrome.tabs.onRemoved <a class="header-anchor" href="#_3-7-监听标签页关闭-chrome-tabs-onremoved" aria-label="Permalink to &quot;3.7 监听标签页关闭：chrome.tabs.onRemoved&quot;">​</a></h3><p>chrome.tabs.onRemoved.addListener(callback) 方法用于监听标签页的关闭。</p><p>参数：</p><ul><li>callback(tabId, removeInfo)：一个回调函数，在标签页关闭时执行。 <ul><li>tabId(Number)：关闭的标签页的 ID。</li><li>removeInfo(Options)：一个对象，包含关闭的标签页的信息。</li><li>如果监听失败，返回错误信息。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 监听标签页关闭</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.tabs.onRemoved.addListener(function(tabId, removeInfo) {</span></span>
<span class="line"><span>  console.log(&#39;Tab removed:&#39;, tabId, removeInfo);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="_4-chrome-runtime" tabindex="-1">4. chrome.runtime <a class="header-anchor" href="#_4-chrome-runtime" aria-label="Permalink to &quot;4. chrome.runtime&quot;">​</a></h2><p>chrome.runtime 是 Chrome 扩展 API 中的一个模块，用于与扩展的运行时环境进行交互。它提供了一些方法和事件，用于获取扩展的信息、发送消息给扩展、监听扩展的事件等。</p><h3 id="_4-1-获取扩展信息-chrome-runtime-getmanifest" tabindex="-1">4.1 获取扩展信息：chrome.runtime.getManifest() <a class="header-anchor" href="#_4-1-获取扩展信息-chrome-runtime-getmanifest" aria-label="Permalink to &quot;4.1 获取扩展信息：chrome.runtime.getManifest()&quot;">​</a></h3><p>chrome.runtime.getManifest() 方法用于获取扩展的清单文件（manifest.json）中的信息。</p><p>返回值：</p><ul><li>一个对象，包含扩展的信息。</li><li>如果获取失败，返回错误信息。</li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 获取扩展信息</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const manifest = chrome.runtime.getManifest();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>console.log(&#39;Extension name:&#39;, manifest.name);</span></span>
<span class="line"><span>console.log(&#39;Extension version:&#39;, manifest.version);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_4-2-发送消息给扩展-chrome-runtime-sendmessage" tabindex="-1">4.2 发送消息给扩展：chrome.runtime.sendMessage() <a class="header-anchor" href="#_4-2-发送消息给扩展-chrome-runtime-sendmessage" aria-label="Permalink to &quot;4.2 发送消息给扩展：chrome.runtime.sendMessage()&quot;">​</a></h3><p>chrome.runtime.sendMessage(extensionId, message, options, callback) 方法用于向扩展发送消息。</p><p>参数：</p><ul><li>extensionId(String)：可选参数，指定要发送消息的扩展的 ID。如果不指定，则默认为当前扩展。</li><li>message(any)：要发送的消息。消息可以是任何类型的数据，具体取决于接收方的需求。</li><li>options(Object)：可选参数，用于配置消息的发送选项。 <ul><li>includeTlsChannelId (Boolean): 如果设置为 true，则会在消息中包含 TLS 通道 ID。这通常用于需要跨多个标签页或窗口进行安全通信的场景。</li><li>targetOrigin (String): 指定消息的目标源。这可以是一个具体的源（如 <a href="https://example.com" target="_blank" rel="noreferrer">https://example.com</a>），也可以是一个通配符（如 *），表示消息可以发送到任何源。</li><li>targetTabId (Number): 指定消息的目标标签页 ID。如果设置了这个选项，消息将只发送到指定的标签页。</li><li>targetFrameId (Number): 指定消息的目标框架 ID。如果标签页包含多个框架，这个选项可以指定消息发送到哪个框架。</li><li>timeout (Number): 指定消息发送的超时时间（毫秒）。如果在指定时间内没有收到响应，发送操作将被取消。</li></ul></li><li>callback(response)：可选参数，用于接收消息的响应。 <ul><li>返回值：</li><li>一个 Promise 对象，用于接收消息的响应。如果发送消息时指定了 callback 参数，则返回的 Promise 对象将被解析为响应数据。如果发送消息时未指定 callback 参数，则返回的 Promise 对象将被解析为 undefined。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 发送消息给扩展</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.sendMessage({ message: &#39;Hello from the popup!&#39; }, function(response) {</span></span>
<span class="line"><span>  console.log(&#39;Response from background script:&#39;, response);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 发送消息给扩展，并指定回调函数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.sendMessage({ message: &#39;Hello from the popup!&#39; }, function(response) {</span></span>
<span class="line"><span>  console.log(&#39;Response from background script:&#39;, response);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 发送消息给扩展，并指定超时时间</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.sendMessage({ message: &#39;Hello from the popup!&#39; }, function(response) {</span></span>
<span class="line"><span>  console.log(&#39;Response from background script:&#39;, response);</span></span>
<span class="line"><span>}, { timeout: 5000 });</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 发送消息给扩展，并指定目标标签页 ID</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.sendMessage({ message: &#39;Hello from the popup!&#39; }, function(response) {</span></span>
<span class="line"><span>  console.log(&#39;Response from background script:&#39;, response);</span></span>
<span class="line"><span>}, { targetTabId: tabId });</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 发送消息给扩展，并指定目标框架 ID</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.sendMessage({ message: &#39;Hello from the popup!&#39; }, function(response) {</span></span>
<span class="line"><span>  console.log(&#39;Response from background script:&#39;, response);</span></span>
<span class="line"><span>}, { targetFrameId: frameId });</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br></div></div><p>在这个示例中，我们向扩展发送了一条消息，并在发送消息时指定了一个回调函数。当扩展接收到消息并处理完成后，回调函数将被调用，并接收到响应数据。</p><h3 id="_4-3-监听扩展事件-chrome-runtime-onmessage" tabindex="-1">4.3 监听扩展事件：chrome.runtime.onMessage <a class="header-anchor" href="#_4-3-监听扩展事件-chrome-runtime-onmessage" aria-label="Permalink to &quot;4.3 监听扩展事件：chrome.runtime.onMessage&quot;">​</a></h3><p>chrome.runtime.onMessage.addListener(callback) 方法用于监听扩展的消息事件。当其他部分（如内容脚本、后台脚本或其他扩展）向当前扩展发送消息时，此方法会触发。</p><p>参数：</p><ul><li>callback(request, sender, sendResponse)：一个回调函数，在接收到扩展的消息时执行。 <ul><li>request(any)：接收到的消息。消息可以是任何类型的数据，具体取决于发送方。</li><li>sender(MessageSender)：发送消息的标签页或扩展的信息。MessageSender 对象包含以下属性： <ul><li>tab(Options)：发送消息的标签页的信息。</li><li>id(Number)：发送消息的标签页或扩展的 ID。</li><li>url(String)：发送消息的标签页的 URL。</li></ul></li><li>sendResponse(response)：一个函数，用于发送响应给发送消息的标签页或扩展。响应可以是任何类型的数据，具体取决于接收方的需求。</li><li>返回值：</li><li>一个布尔值，表示是否异步响应。如果返回 true，则表示 sendResponse 函数将异步调用，即在 callback 函数返回后调用。如果返回 false 或未返回任何值，则表示 sendResponse 将同步调用，即在 callback 函数返回前调用。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 监听扩展事件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.onMessage.addListener(function(request, sender, sendResponse) {</span></span>
<span class="line"><span>  console.log(&#39;Message received:&#39;, request);</span></span>
<span class="line"><span>  console.log(&#39;Sender:&#39;, sender);</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // 处理消息</span></span>
<span class="line"><span>  if (request.message === &#39;hello&#39;) {</span></span>
<span class="line"><span>    sendResponse({ response: &#39;Hello from the background script!&#39; });</span></span>
<span class="line"><span>  } else {</span></span>
<span class="line"><span>    sendResponse({ response: &#39;Unknown message&#39; });</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // 异步响应</span></span>
<span class="line"><span>  return true;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -- 第二种写法 --</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // 异步响应</span></span>
<span class="line"><span>  setTimeout(function() {</span></span>
<span class="line"><span>    sendResponse({ response: &#39;Hello, sender!&#39; });</span></span>
<span class="line"><span>  }, 1000);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // 同步响应</span></span>
<span class="line"><span>  return { response: &#39;Hello, sender!&#39; };</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><p>在这个示例中，我们监听了 chrome.runtime.onMessage 事件，并在接收到消息时打印了消息内容和发送者信息。然后，我们根据消息内容发送了相应的响应。返回 true 表示我们将异步处理响应。</p><h3 id="_4-4-监听扩展安装-chrome-runtime-oninstalled" tabindex="-1">4.4 监听扩展安装：chrome.runtime.onInstalled <a class="header-anchor" href="#_4-4-监听扩展安装-chrome-runtime-oninstalled" aria-label="Permalink to &quot;4.4 监听扩展安装：chrome.runtime.onInstalled&quot;">​</a></h3><p>chrome.runtime.onInstalled.addListener(callback) 方法用于监听扩展的安装事件。当扩展被安装或更新时，此方法会触发。</p><p>参数：</p><ul><li>callback(details)：一个回调函数，在扩展安装或更新时执行。 <ul><li>details(Object)：一个对象，包含安装或更新的详细信息。</li><li>reason(String)：安装或更新的原因。可能的值有： <ul><li>install：扩展被安装。</li><li>update：扩展被更新。</li><li>chrome_update：Chrome 浏览器被更新。</li></ul></li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 监听扩展安装事件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.onInstalled.addListener(function(details) {</span></span>
<span class="line"><span>  console.log(&#39;Extension installed:&#39;, details);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // 执行安装或更新后的操作</span></span>
<span class="line"><span>  if (details.reason === &#39;install&#39;) {</span></span>
<span class="line"><span>    // 扩展被安装时执行的操作</span></span>
<span class="line"><span>  } else if (details.reason === &#39;update&#39;) {</span></span>
<span class="line"><span>    // 扩展被更新时执行的操作</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="_4-5-监听扩展更新-chrome-runtime-onupdateavailable" tabindex="-1">4.5 监听扩展更新：chrome.runtime.onUpdateAvailable <a class="header-anchor" href="#_4-5-监听扩展更新-chrome-runtime-onupdateavailable" aria-label="Permalink to &quot;4.5 监听扩展更新：chrome.runtime.onUpdateAvailable&quot;">​</a></h3><p>chrome.runtime.onUpdateAvailable.addListener(callback) 方法用于监听扩展的更新事件。当扩展有可用的更新时，此方法会触发。</p><p>参数：</p><ul><li>callback(details)：一个回调函数，在扩展有可用的更新时执行。 <ul><li>details(Object)：一个对象，包含更新的详细信息。</li><li>previousVersion(String)：扩展的上一个版本号。</li><li>appId(String)：扩展的应用 ID。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 监听扩展更新事件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.onUpdateAvailable.addListener(function(details) {</span></span>
<span class="line"><span>  console.log(&#39;Extension update available:&#39;, details);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // 执行更新后的操作</span></span>
<span class="line"><span>  // 可以使用 chrome.runtime.reload() 方法重新加载扩展</span></span>
<span class="line"><span>  chrome.runtime.reload();</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_4-6-监听扩展卸载-chrome-runtime-onuninstalled" tabindex="-1">4.6 监听扩展卸载：chrome.runtime.onUninstalled <a class="header-anchor" href="#_4-6-监听扩展卸载-chrome-runtime-onuninstalled" aria-label="Permalink to &quot;4.6 监听扩展卸载：chrome.runtime.onUninstalled&quot;">​</a></h3><p>chrome.runtime.onUninstalled.addListener(callback) 方法用于监听扩展的卸载事件。当扩展被卸载时，此方法会触发。</p><p>参数：</p><ul><li>callback(details)：一个回调函数，在扩展被卸载时执行。 <ul><li>details(Object)：一个对象，包含卸载的详细信息。</li><li>reason(String)：卸载的原因。可能的值有： <ul><li>uninstalled：扩展被手动卸载。</li><li>spoofer：扩展被恶意软件或恶意软件的插件卸载。</li><li>update：扩展被更新时卸载。</li></ul></li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 监听扩展卸载事件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.onUninstalled.addListener(function(details) {</span></span>
<span class="line"><span>  console.log(&#39;Extension uninstalled:&#39;, details);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // 执行卸载后的操作</span></span>
<span class="line"><span>  // 可以执行清理操作，如删除扩展的数据或执行其他清理任务</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_4-7-监听扩展启动-chrome-runtime-onstartup" tabindex="-1">4.7 监听扩展启动：chrome.runtime.onStartup <a class="header-anchor" href="#_4-7-监听扩展启动-chrome-runtime-onstartup" aria-label="Permalink to &quot;4.7 监听扩展启动：chrome.runtime.onStartup&quot;">​</a></h3><p>chrome.runtime.onStartup.addListener(callback) 方法用于监听扩展的启动事件。当扩展启动时，此方法会触发。</p><p>参数：</p><ul><li>callback()：一个回调函数，在扩展启动时执行。</li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 监听扩展启动事件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.onStartup.addListener(function() {</span></span>
<span class="line"><span>  console.log(&#39;Extension started&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // 执行启动后的操作</span></span>
<span class="line"><span>  // 可以执行初始化操作，如加载数据或执行其他启动任务</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_4-8-监听扩展激活-chrome-runtime-onactivated" tabindex="-1">4.8 监听扩展激活：chrome.runtime.onActivated <a class="header-anchor" href="#_4-8-监听扩展激活-chrome-runtime-onactivated" aria-label="Permalink to &quot;4.8 监听扩展激活：chrome.runtime.onActivated&quot;">​</a></h3><p>chrome.runtime.onActivated.addListener(callback) 方法用于监听扩展的激活事件。当扩展被激活时，此方法会触发。</p><p>参数：</p><ul><li>callback(activeInfo)：一个回调函数，在扩展激活时执行。 <ul><li>activeInfo(Options)：一个对象，包含激活的扩展的信息。</li><li>如果监听失败，返回错误信息。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 监听扩展激活事件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.runtime.onActivated.addListener(function(activeInfo) {</span></span>
<span class="line"><span>  console.log(&#39;Extension activated:&#39;, activeInfo);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // 执行激活后的操作</span></span>
<span class="line"><span>  // 可以执行初始化操作，如加载数据或执行其他激活任务</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="_5-chrome-window" tabindex="-1">5. chrome.window <a class="header-anchor" href="#_5-chrome-window" aria-label="Permalink to &quot;5. chrome.window&quot;">​</a></h2><p>chrome.window 是 Chrome 扩展 API 中的一个模块，用于操作浏览器窗口。</p><h3 id="_5-1-打开新窗口-chrome-windows-create" tabindex="-1">5.1 打开新窗口：chrome.windows.create() <a class="header-anchor" href="#_5-1-打开新窗口-chrome-windows-create" aria-label="Permalink to &quot;5.1 打开新窗口：chrome.windows.create()&quot;">​</a></h3><p>chrome.windows.create(options, callback) 方法用于打开一个新的浏览器窗口。</p><p>参数：</p><ul><li>options(Options)：一个对象，包含窗口的创建选项。 <ul><li>url(String)：要打开的 URL。</li><li>focused(Boolean)：是否将新窗口设置为焦点窗口。</li><li>type(String)：窗口的类型。可能的值有： <ul><li>normal：普通窗口。</li><li>popup：弹出窗口。</li><li>panel：面板窗口。</li></ul></li></ul></li><li>callback(window)：一个回调函数，在窗口创建完成后执行。 <ul><li>返回值：</li><li>一个对象，包含新窗口的信息。</li><li>如果创建失败，返回错误信息。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 打开新窗口</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.windows.create({ url: &#39;URL_ADDRESS&#39; }, function(window) {</span></span>
<span class="line"><span>  console.log(&#39;New window created:&#39;, window);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_5-2-关闭窗口-chrome-windows-remove" tabindex="-1">5.2 关闭窗口：chrome.windows.remove() <a class="header-anchor" href="#_5-2-关闭窗口-chrome-windows-remove" aria-label="Permalink to &quot;5.2 关闭窗口：chrome.windows.remove()&quot;">​</a></h3><p>chrome.windows.remove(windowId, callback) 方法用于关闭指定窗口。</p><p>参数：</p><ul><li>windowId(Number)：要关闭的窗口的 ID。</li><li>callback()：一个回调函数，在窗口关闭完成后执行。</li><li>如果关闭失败，返回错误信息。</li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 关闭窗口</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.windows.remove(windowId, function() {</span></span>
<span class="line"><span>  console.log(&#39;Window removed&#39;);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_5-3-获取窗口信息-chrome-windows-get" tabindex="-1">5.3 获取窗口信息：chrome.windows.get() <a class="header-anchor" href="#_5-3-获取窗口信息-chrome-windows-get" aria-label="Permalink to &quot;5.3 获取窗口信息：chrome.windows.get()&quot;">​</a></h3><p>chrome.windows.get(windowId, callback) 方法用于获取指定窗口的信息。</p><p>参数：</p><ul><li>windowId(Number)：要获取信息的窗口的 ID。</li><li>callback(window)：一个回调函数，在获取窗口信息完成后执行。 <ul><li>返回值：</li><li>一个对象，包含窗口的信息。</li></ul></li></ul><p>示例：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 获取窗口信息</span></span>
<span class="line"><span></span></span>
<span class="line"><span>chrome.windows.get(windowId, function(window) {</span></span>
<span class="line"><span>  console.log(&#39;Window information:&#39;, window);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_5-4-更新窗口的属性-chrome-windows-update" tabindex="-1">5.4 更新窗口的属性:chrome.windows.update() <a class="header-anchor" href="#_5-4-更新窗口的属性-chrome-windows-update" aria-label="Permalink to &quot;5.4 更新窗口的属性:chrome.windows.update()&quot;">​</a></h3><p>chrome.windows.update(windowId, updateInfo, callback) 方法用于更新窗口的属性。仅指定要更改的属性；未指定的属性会保持不变。</p>`,140)]))}const d=a(p,[["render",i]]);export{m as __pageData,d as default};
